"""Release GPU memory held by ASR / Torch / MT between pipeline stages."""

from __future__ import annotations

import gc
import logging
from typing import Any

_log = logging.getLogger("transub_engine.runtime_release")


def release_gpu_memory(*, reason: str = "", unload_models: bool = True) -> dict[str, Any]:
    """
    Best-effort free of CUDA caches so a follow-up process (e.g. llama-server)
    can claim VRAM after Whisper / Demucs / SenseVoice / Opus MT.

    When unload_models=True (default for API), drop process-level MT caches so
    weights are actually collectable — empty_cache alone cannot free live models.
    """
    freed: list[str] = []
    errors: list[str] = []

    if unload_models:
        try:
            from .mt import opus_ct2

            n = opus_ct2.clear_model_cache()
            if n:
                freed.append(f"mt_cache:{n}")
            else:
                freed.append("mt_cache:0")
        except Exception as err:
            errors.append(f"mt_cache:{err}")

        try:
            from .asr import whisper_fw

            n = whisper_fw.clear_model_cache()
            if n:
                freed.append(f"whisper_cache:{n}")
            else:
                freed.append("whisper_cache:0")
        except Exception as err:
            errors.append(f"whisper_cache:{err}")

        try:
            from .vad import whisperseg

            n = whisperseg.clear_segmenter_cache()
            if n:
                freed.append(f"whisperseg_cache:{n}")
            else:
                freed.append("whisperseg_cache:0")
        except Exception as err:
            errors.append(f"whisperseg_cache:{err}")

        try:
            from .asr import sensevoice

            n = sensevoice.clear_model_cache()
            if n:
                freed.append(f"sensevoice_cache:{n}")
            else:
                freed.append("sensevoice_cache:0")
        except Exception as err:
            errors.append(f"sensevoice_cache:{err}")

        try:
            from .asr import reazon_k2

            n = reazon_k2.clear_model_cache()
            freed.append(f"reazon_k2_cache:{n}")
        except Exception as err:
            errors.append(f"reazon_k2_cache:{err}")

        try:
            from .asr import qwen3_asr

            n = qwen3_asr.clear_model_cache()
            freed.append(f"qwen3_asr_cache:{n}")
        except Exception as err:
            errors.append(f"qwen3_asr_cache:{err}")

        try:
            from .asr import parakeet

            n = parakeet.clear_model_cache()
            freed.append(f"parakeet_cache:{n}")
        except Exception as err:
            errors.append(f"parakeet_cache:{err}")

        try:
            from .asr import wav2vec_align

            n = wav2vec_align.clear_align_model_cache()
            freed.append(f"wav2vec_align_cache:{n}")
        except Exception as err:
            errors.append(f"wav2vec_align_cache:{err}")

    gc.collect()
    freed.append("gc")

    try:
        import torch  # type: ignore

        if torch.cuda.is_available():
            try:
                torch.cuda.synchronize()
            except Exception:
                pass
            torch.cuda.empty_cache()
            try:
                torch.cuda.ipc_collect()
            except Exception:
                pass
            freed.append("torch.cuda.empty_cache")
    except Exception as err:
        errors.append(f"torch:{err}")

    try:
        # CTranslate2 keeps allocator pools; clear if API exists.
        import ctranslate2  # type: ignore

        clear_fn = getattr(ctranslate2, "clear_cache", None) or getattr(
            getattr(ctranslate2, "cuda", None), "clear_cache", None
        )
        if callable(clear_fn):
            clear_fn()
            freed.append("ctranslate2.clear_cache")
    except Exception as err:
        errors.append(f"ctranslate2:{err}")

    _log.info("release_gpu_memory reason=%s freed=%s errors=%s", reason or "-", freed, errors)
    return {
        "ok": True,
        "reason": reason or "",
        "freed": freed,
        "errors": errors,
        "hint": "已尽量释放引擎进程内显存；若仍不足请重启引擎进程",
    }
